using DomainModel.ViewModels.Province; using Framework.Common.Seo; namespace DataAccess.Repositories.Province; public static class ProvinceMapper { public static DomainModel.Models.Province ToEntity(ProvinceAddEditModel m)=>new(){ProvinceName=m.ProvinceName.Trim(),IsActive=m.IsActive,DisplayOrder=m.DisplayOrder,Slug=string.IsNullOrWhiteSpace(m.Slug)?null:SeoHelper.ToSlug(m.Slug),SeoTitle=m.SeoTitle,SeoDescription=m.SeoDescription,SeoKeywords=m.SeoKeywords,CanonicalUrl=m.CanonicalUrl,OpenGraphImageUrl=m.OpenGraphImageUrl,IsIndexable=m.IsIndexable,IsFollow=m.IsFollow}; public static void MapForUpdate(ProvinceAddEditModel m,DomainModel.Models.Province e){e.ProvinceName=m.ProvinceName.Trim();e.IsActive=m.IsActive;e.DisplayOrder=m.DisplayOrder;e.Slug=string.IsNullOrWhiteSpace(m.Slug)?null:SeoHelper.ToSlug(m.Slug);e.SeoTitle=m.SeoTitle;e.SeoDescription=m.SeoDescription;e.SeoKeywords=m.SeoKeywords;e.CanonicalUrl=m.CanonicalUrl;e.OpenGraphImageUrl=m.OpenGraphImageUrl;e.IsIndexable=m.IsIndexable;e.IsFollow=m.IsFollow;} }
